    correctAnswer: '单链接（MIN）：簇间距离定义为两簇中最近两点之间的距离。倾向于产生"拉长"的链状簇，对噪声敏感。全链接（MAX）：簇间距离定义为两簇中最远两点之间的距离。倾向于产生紧凑的球形簇，对异常值敏感。平均链接（Average）：簇间距离定义为两簇所有点对的平均距离。是折中方案，对噪声的鲁棒性较好。单链接可能会导致"链效应"，全链接倾向于产生直径相近的簇。Ward方法是最常用的替代方案，基于最小化簇内方差增长，倾向于产生大小相近的簇。',
    explanation: '不同的链接方法会影响聚类的最终形状和结构。',
