    stem: '简述Hold-out验证、K折交叉验证和留一交叉验证（LOOCV）的区别及适用场景。',
    correctAnswer: 'Hold-out验证：将数据简单划分为训练集和测试集（如7:3），一次训练一次评估。适用于数据量很大的场景，简单快速但评估结果受划分方式影响大。K折交叉验证：将数据等分为K份，每次用K-1份训练、1份验证，重复K次取平均。K=5或10最常用，平衡了计算成本和评估稳定性。LOOCV：每次留一个样本做验证，其余全部训练，重复N次。偏差最小（利用几乎所有数据训练），但方差大且计算成本极高（需训练N次模型）。适用于极小样本量的场景。',
    explanation: 'K折交叉验证是实践中最常用的模型评估方法。',
