    correctAnswer: '卡方检验的基本思想是比较实际观察频数与在H₀成立下的理论期望频数之间的差异。如果H₀成立，两者应接近，χ²值较小；如果差异很大，χ²值增大。χ²统计量衡量的是标准化后的差异总和。当H₀成立时，χ²近似服从卡方分布（大样本下），将χ²值与卡方分布的临界值比较决定是否拒绝H₀。',
    explanation: '卡方检验是分类数据分析最核心的方法。',
