    correctAnswer: '在独立性假设下，期望频数 f_e = (行合计×列合计)/总合计。例如2×2表中，第一行第一列的期望值=(第一行总和×第一列总和)/n。期望频数不应过小的原因：卡方检验的分布理论依赖于大样本（渐近卡方分布）。当期望频数<5时，χ²统计量的真实分布与理论卡方分布的偏差较大，导致P值不准确（Ⅰ类错误率偏离名义水平）。通常要求所有期望频数≥5，或至少80%的单元格满足此条件。',
