    correctAnswer: 'H₀:性别与态度独立，H₁:不独立。列联表：男(140,60,200)，女(100,100,200)，合计(240,160,400)。期望频数：男-喜欢=240×200/400=120，男-不喜欢=160×200/400=80，女-喜欢=240×200/400=120，女-不喜欢=160×200/400=80。χ²=(140-120)²/120+(60-80)²/80+(100-120)²/120+(100-80)²/80=3.333+5+3.333+5=16.667。df=1，χ²=16.667>3.841, P<0.001。拒绝H₀。结论：性别与锻炼态度存在极显著的关联，男生中喜欢锻炼的比例(70%)高于女生(50%)。',
