    correctAnswer: 'FWER控制（如Bonferroni、Tukey HSD）：将犯任意一个假阳性错误的概率控制在α以下。适用场景：①证实性研究（Confirmatory），如药品审批（不能接受任何一个假阳性）；②比较组数较少时。缺点：过于保守，检验功效低。FDR控制（如Benjamini-Hochberg方法）：控制所有拒绝中假阳性比例的期望值不超q。适用场景：①探索性研究（Exploratory），如基因表达差异分析（数千个基因同时比较，允许一定比例的假阳性）；②大规模多重比较时。相比FWER，FDR在检验功效上有显著优势。选择取决于研究目的和对假阳性的容忍度。',
