    correctAnswer: '指数平滑原理：预测值是过去观测值的加权平均，权重以几何级数递减（越近越重要）。简单指数平滑（SES）：F_{t+1}=αY_t+(1-α)F_t，仅适用于水平序列（无趋势无季节）。Holt方法：增加趋势平滑方程T_t=β(L_t-L_{t-1})+(1-β)T_{t-1}，适用于带趋势的序列。Winters方法：进一步增加季节平滑方程，适用于带趋势和季节的序列。三者是递进关系：SES(1参数)→Holt(2参数)→Winters(3参数加法或乘法)。每个扩展解决更复杂的数据模式。',
    explanation: '指数平滑系列方法因其简单和稳健而在工业界广泛应用。',
