    stem: '某视频平台新上线，没有任何用户行为数据。请设计一个从冷启动到成熟的推荐系统演进方案。',
    correctAnswer: '阶段一（冷启动）：基于内容的推荐——利用视频的元数据（标题、分类、标签、导演/演员）匹配用户注册时选择的兴趣标签。同时使用热门推荐和编辑精选作为兜底策略。阶段二（积累数据）：引入协同过滤——当积累一定用户行为数据（观看、点赞、收藏）后，逐步加入基于物品的协同过滤（视频相似）。阶段三（混合推荐）：将基于内容和协同过滤的结果通过加权、切换或排序学习进行融合。引入矩阵分解或深度学习模型（如YouTube DNN）学习用户和视频的隐式表示。阶段四（精细化）：引入上下文信息（时间、设备、网络状态）和实时特征，实现个性化的场景推荐。全过程进行A/B测试验证。',
    explanation: '从冷启动到成熟的完整推荐系统演进路径。',
