    stem: '在电商推荐中，用户-物品评分矩阵通常极其稀疏（稀疏度>99%）。分析这对协同过滤和矩阵分解带来的挑战，并提出解决策略。',
    correctAnswer: '挑战：1）相似度计算不可靠：稀疏矩阵中两个用户共同评分的物品极少，导致用户相似度估计方差大；2）矩阵分解容易过拟合：观察到的评分太少，隐因子学习不稳定；3）冷启动用户/物品：完全没有或只有极少评分的用户/物品无法嵌入隐空间。解决策略：1）使用隐式反馈：除评分外利用点击、浏览、加购、停留时长等（数据量大得多）；2）正则化：加强L2正则化防止过拟合；3）偏差项：加入用户偏差（有些用户评分偏高）和物品偏差（有些物品评分偏高）来改善预测；4）SVD++等融合隐式反馈的模型；5）基于邻域的方法作为补充（对稀疏数据KNN有时比矩阵分解更鲁棒）；6）内容特征的引入（Hybrid模型）。',
