// 系统题库 = 原概念题 + 计算题（calcQuestions，按教材公式生成）+ 指导书变体题（gqv-，知识点与指导书一致）
export const questionBank: Question[] = [...baseQuestionBank, ...calcQuestions, ...guideVariantQuestions];

// 全部题库 = 系统原题库 + 竞赛筛选题库（screened）+ 指导书原题（guide）
export const allQuestions: Question[] = [...questionBank, ...screenedQuestionBank, ...guideQuestionBank];

export function getQuestionsByBank(bank: BankFilter = 'all'): Question[] {
  if (bank === 'all') return allQuestions;
  if (bank === 'screened') return screenedQuestionBank;
  if (bank === 'guide') return guideQuestionBank;
  return questionBank;
}

export function getQuestionById(id: string): Question | undefined {
  return questionBank.find((q) => q.id === id) ?? screenedQuestionBank.find((q) => q.id === id) ?? guideQuestionBank.find((q) => q.id === id);
}

// Utility to filter questions
export function filterQuestions(filters: {
  types?: string[];
  chapters?: string[];
  knowledgePoints?: string[];
}): Question[] {
  return questionBank.filter((q) => {
    if (filters.types && filters.types.length > 0 && !filters.types.includes(q.type)) return false;
    if (filters.chapters && filters.chapters.length > 0 && !filters.chapters.includes(q.chapter)) return false;
    if (filters.knowledgePoints && filters.knowledgePoints.length > 0 && !filters.knowledgePoints.includes(q.knowledgePoint)) return false;
    return true;
  });
}

// Select random questions from filtered pool
export function selectRandomQuestions(
  pool: Question[],
  count: number
): Question[] {
  const shuffled = [...pool].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(count, shuffled.length));
}
